import React from "react";
import CameraScanner from "./CameraScanner";
import RiskMeter from "./RiskMeter";

function Home({
  capturedImage,
  ocrText,
  riskScore,
  riskLevel,
  riskReason,
  detectedAdditives,
  loading,
  clearScan,
  handleCapture,
  handleImageUpload,
}) {

  const fileInputRef = React.useRef(null);

  const handleDragOver = (e) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      const file = e.dataTransfer.files[0];
      processFile(file);
    }
  };

  const processFile = (file) => {
    if (!file.type.startsWith("image/")) {
      alert("Please upload a valid image file.");
      return;
    }
    const reader = new FileReader();
    reader.onload = (event) => {
      handleCapture(event.target.result);
    };
    reader.readAsDataURL(file);
  };

  const triggerFileSelect = () => {
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  return (
    <div className="home-container">
      {/* Hero Section */}
      <header className="hero text-center">
        <h1 className="hero-title animate-fade-in">SAFE BITE</h1>
        <p className="hero-subtitle animate-fade-in-delayed">
          Scan ingredient labels to detect food additives and assess toxicological risks.
        </p>
      </header>

      {/* Main Grid Dashboard */}
      <div className="dashboard-grid">
        {/* Left Side: Scan / Upload / OCR */}
        <div className="dashboard-col left-col">
          {/* Camera Scan Card */}
          <div className="card glass scanner-card">
            <h2>📷 Scan Using Camera</h2>
            <p className="card-sub">Position the ingredients list directly in front of the lens.</p>
            <CameraScanner onCapture={handleCapture} />
          </div>

          {/* Image Upload Card */}
          <div className="card glass upload-card">
            <h2>📁 Upload Image</h2>
            <p className="card-sub">Drag and drop an image of an ingredient list, or browse files.</p>

            <div
              className="dropzone"
              onDragOver={handleDragOver}
              onDrop={handleDrop}
              onClick={triggerFileSelect}
            >
              <div className="dropzone-content">
                <span className="upload-icon">📤</span>
                <p>Drag & Drop or Click to Browse</p>
                <span className="file-hint">Supports PNG, JPG, JPEG</span>
              </div>
              <input
                type="file"
                ref={fileInputRef}
                className="hidden-file-input"
                accept="image/*"
                onChange={(e) => {
                  if (e.target.files && e.target.files[0]) {
                    processFile(e.target.files[0]);
                  }
                }}
              />
            </div>
          </div>

          {/* Captured Image Preview */}
          {capturedImage && (
            <div className="card glass preview-card animate-slide-up">
              <div className="card-header-actions">
                <h2>Captured Image</h2>
                <button className="btn-secondary" onClick={clearScan}>
                  🔄 Clear / Recapture
                </button>
              </div>
              <div className="image-wrapper">
                <img src={capturedImage} alt="Captured Label Preview" />
              </div>
            </div>
          )}

          {/* OCR Result Card */}
          <div className="card glass ocr-card">
            <h2>OCR Result</h2>
            <div className="ocr-text-container">
              {loading ? (
                <div className="loading-container">
                  <div className="spinner"></div>
                  <p>Extracting text using Tesseract.js OCR...</p>
                </div>
              ) : ocrText ? (
                <p className="ocr-text">{ocrText}</p>
              ) : (
                <p className="no-ocr-text">No text scanned yet. Use the camera or upload an image to start.</p>
              )}
            </div>
          </div>
        </div>

        {/* Right Side: Risk Assessment */}
        <div className="dashboard-col right-col">
          {/* Risk Meter Card */}
          <div className="card glass meter-card text-center">
            <h2>Food Risk Meter</h2>
            <p className="card-sub">Consolidated health hazard index based on INS ratings.</p>

            <div className="risk-display-container">
              <RiskMeter score={riskScore} />

              <div className="risk-summary animate-fade-in">
                <div className="risk-stats">
                  <div className="stat-box">
                    <span className="stat-label">Overall Risk</span>
                    <span className="stat-val">{riskScore}%</span>
                  </div>
                  <div className="stat-box">
                    <span className="stat-label">Risk Level</span>
                    <span className={`stat-val level-${riskLevel.toLowerCase()}`}>
                      {riskLevel}
                    </span>
                  </div>
                </div>

                {riskReason && (
                  <div className="risk-reasons-box text-left">
                    <h3>Risk Level Justification</h3>
                    <div className="reasons-list">
                      {riskReason.split("\n").map((line, idx) => (
                        <p key={idx} className="reason-line">
                          {line}
                        </p>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* Detected Additives Card */}
          <div className="card glass additives-card">
            <h2>Detected Additives ({detectedAdditives.length})</h2>

            <div className="additives-list-container">
              {detectedAdditives.length > 0 ? (
                <div className="additives-grid">
                  {detectedAdditives.map((item, index) => {
                    const isHigh = item.high_risk_flag === 1 || item.high_risk_flag === true;
                    return (
                      <div
                        key={index}
                        className={`additive-item-card card ${
                          isHigh ? "border-high" : "border-normal"
                        }`}
                      >
                        <div className="additive-item-header">
                          <div>
                            <span className="ins-badge">INS {item.code}</span>
                            <h3>{item.name}</h3>
                          </div>
                          <span className={`badge ${isHigh ? "badge-high" : "badge-normal"}`}>
                            {isHigh ? "🔴 High Risk" : "🟢 Normal"}
                          </span>
                        </div>

                        <div className="additive-details">
                          <p>
                            <strong>Category:</strong> {item.category}
                          </p>
                          <p>
                            <strong>Description:</strong> {item.description}
                          </p>
                          <p className="additive-score-row">
                            <strong>Addtive Risk:</strong>{" "}
                            <span className={`score-tag ${isHigh ? "text-high" : "text-normal"}`}>
                              {item.risk_score}%
                            </span>
                          </p>
                          {item.risk_score_reason && (
                            <div className="score-reason-box">
                              <strong>Evaluation:</strong>
                              <p className="reason-text">{item.risk_score_reason}</p>
                            </div>
                          )}
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <p className="no-additives-text">
                  No food additives detected. Perform a scan to view toxicity details.
                </p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Home;
